const SEED_ROWS = [
  // ---------------- CHEST ----------------
  ['Barbell bench press', 'Barbell on a flat bench. Lie back with your eyes under the bar, feet flat on the floor and shoulder blades pulled back and down. Grip a little wider than shoulder width, lift the bar off the rack, lower it slowly to your lower chest, then push it straight back up until your arms are straight.', ['push'], ['chest', 'triceps', 'shoulders'], 'weightlifting', 1],
  ['Incline barbell bench press', 'Barbell on a bench set to about 30 degrees. Lie back with shoulder blades pulled together, grip a little wider than shoulder width and lift the bar off the rack. Lower it slowly to your upper chest, just below the collarbones, then press it back up. Works the upper chest more than the flat bench.', ['push'], ['chest', 'shoulders', 'triceps'], 'weightlifting', 1],
  ['Decline barbell bench press', 'Barbell on a bench that slopes head-down. Hook your feet under the pads, lie back and grip a little wider than shoulder width. Lower the bar to your lower chest, then press back up. Keep your wrists straight and directly above your elbows.', ['push'], ['chest', 'triceps'], 'weightlifting', 2],
  ['Dumbbell bench press', 'Two dumbbells and a flat bench. Sit with the dumbbells on your thighs, lie back and use your knees to kick them up to chest height. Press them up until your arms are straight, then lower them slowly until you feel a stretch across your chest. Dumbbells let each arm work on its own.', ['push'], ['chest', 'triceps', 'shoulders'], 'weightlifting', 2],
  ['Incline dumbbell press', 'Two dumbbells and a bench set to about 30 degrees. Lie back, dumbbells at shoulder height with palms facing slightly inward. Press them up and slightly together until your arms are straight, then lower slowly until your elbows are just below the bench.', ['push'], ['chest', 'shoulders', 'triceps'], 'weightlifting', 2],
  ['Decline dumbbell press', 'Two dumbbells and a bench that slopes head-down. Hook your feet under the pads, lie back and hold the dumbbells at the sides of your lower chest. Press them up and slightly together, squeeze your chest at the top, then lower with control.', ['push'], ['chest', 'triceps'], 'weightlifting', 2],
  ['Machine chest press', 'Seated chest press machine. Adjust the seat so the handles line up with the middle of your chest. Sit tall with your back against the pad, grip the handles and push forward until your arms are nearly straight, then let them come back slowly. Do not slam the weight stack.', ['push'], ['chest', 'triceps'], 'weightlifting', 2],
  ['Smith machine bench press', 'Smith machine (the bar that runs on fixed rails) with a flat bench underneath. Position the bench so the bar comes down to your lower chest. Unhook the bar by rotating it, lower it slowly to your chest, then press it up and re-hook at the end. The rails guide the bar so you only control the up and down.', ['push'], ['chest', 'triceps', 'shoulders'], 'weightlifting', 2],
  ['Floor press', 'Barbell or dumbbells while lying on the floor. Lie on your back with knees bent, hold the weight above your chest and lower it until the backs of your upper arms touch the floor. Pause for a moment, then press back up. The floor limits how far you go, which is easier on the shoulders.', ['push'], ['chest', 'triceps'], 'weightlifting', 2],
  ['Dumbbell fly', 'Two light dumbbells and a flat bench. Lie back with the dumbbells held above your chest, palms facing each other and a slight bend in your elbows. Open your arms out wide in an arc until you feel a stretch across your chest, then bring them back together as if hugging a tree. Keep the elbow bend the same throughout.', ['push'], ['chest'], 'weightlifting', 3],
  ['Incline dumbbell fly', 'Two light dumbbells and a bench set to about 30 degrees. Lie back with the dumbbells above your chest, palms facing each other and elbows slightly bent. Lower your arms out wide in an arc until you feel a stretch in the upper chest, then squeeze them back together over your chest.', ['push'], ['chest'], 'weightlifting', 3],
  ['Cable fly', 'Cable machine with a handle on each side, set at chest height. Stand in the middle holding one handle in each hand, take a step forward and lean slightly. With a slight bend in your elbows, bring your hands together in front of your chest, then let them open back out slowly.', ['push'], ['chest'], 'weightlifting', 3],
  ['Low-to-high cable fly', 'Cable machine with the pulleys set at the lowest position. Hold a handle in each hand, step forward and start with your hands by your hips. Sweep them up and inward until they meet at shoulder height, then lower slowly. Targets the upper chest.', ['push'], ['chest', 'shoulders'], 'weightlifting', 3],
  ['High-to-low cable fly', 'Cable machine with the pulleys set at the highest position. Hold a handle in each hand, step forward and start with your hands up and out to the sides. Sweep them down and inward until they meet in front of your hips, then let them rise slowly. Targets the lower chest.', ['push'], ['chest'], 'weightlifting', 3],
  ['Pec deck', 'Pec deck or chest fly machine. Sit with your back against the pad and adjust the seat so the handles are level with your chest. Place your forearms or hands on the pads, then squeeze them together in front of you. Let them open back out slowly until you feel a stretch.', ['push'], ['chest'], 'weightlifting', 3],

  // ---------------- BACK ----------------
  ['Conventional deadlift', 'Barbell on the floor. Stand with your feet under the bar about hip width apart, bend down and grip the bar just outside your legs. Flatten your back, lift your chest and take a deep breath. Push the floor away with your legs and stand up tall, keeping the bar close to your body. Lower it back down by pushing your hips back first. Keep your back flat throughout.', ['pull', 'legs', 'full-body'], ['back', 'hamstrings', 'glutes'], 'weightlifting', 1],
  ['Sumo deadlift', 'Barbell on the floor. Stand with a wide stance, toes pointed out, and grip the bar with your hands inside your knees. Push your knees out over your toes, keep your chest up and your back flat, then drive through your feet to stand tall. Lower with control.', ['pull', 'legs', 'full-body'], ['glutes', 'quads', 'hamstrings', 'back'], 'weightlifting', 1],
  ['Trap bar deadlift', 'Trap bar (the hexagon-shaped bar you stand inside). Stand in the middle, bend down and grip the handles at your sides. Flatten your back, push your hips back slightly, then push the floor away to stand up tall. The handles at your sides make this easier on the lower back than a straight bar.', ['pull', 'legs', 'full-body'], ['quads', 'glutes', 'hamstrings', 'back'], 'weightlifting', 1],
  ['Rack pull', 'Barbell resting on the safety pins of a squat rack, set at about knee height. Stand close to the bar, hinge at the hips and grip it just outside your legs. Drive your hips forward to stand tall and squeeze your upper back at the top, then lower back to the pins.', ['pull'], ['back', 'glutes', 'hamstrings'], 'weightlifting', 1],
  ['Barbell bent-over row', 'Barbell. Stand with feet hip width apart holding the bar, then hinge forward at the hips until your torso is at about 45 degrees with a flat back. Pull the bar up to your lower ribs by driving your elbows back, squeeze your shoulder blades together, then lower slowly.', ['pull'], ['back', 'biceps'], 'weightlifting', 1],
  ['Pendlay row', 'Barbell on the floor. Hinge forward until your torso is parallel to the floor and grip the bar. Pull it explosively to your lower chest, then lower it all the way back to the floor and let it rest for a moment before the next rep. Your torso stays parallel the whole time.', ['pull'], ['back', 'biceps'], 'weightlifting', 2],
  ['T-bar row', 'T-bar row station or a barbell wedged into a corner with a V-handle under it. Straddle the bar, hinge forward with a flat back and grip the handles. Pull the weight up to your stomach by driving your elbows back, squeeze your shoulder blades, then lower with control.', ['pull'], ['back', 'biceps'], 'weightlifting', 2],
  ['One-arm dumbbell row', 'One dumbbell and a bench. Place your left hand and left knee on the bench, hold the dumbbell in your right hand with your back flat. Pull the dumbbell up toward your hip, leading with your elbow, then lower it slowly. Keep your torso still. Switch sides.', ['pull'], ['back', 'biceps'], 'weightlifting', 2],
  ['Chest-supported dumbbell row', 'Two dumbbells and a bench set to about 45 degrees. Lie face down on the bench with your chest on the pad and the dumbbells hanging below you. Pull them up by driving your elbows back, pause at the top, then lower slowly. The bench support means no strain on your lower back.', ['pull'], ['back', 'biceps'], 'weightlifting', 2],
  ['Seated cable row', 'Seated cable row machine with a V-handle. Sit with your feet on the platform and knees slightly bent, hold the handle with arms extended and back straight. Pull the handle to your belly, keeping your elbows close and shoulders back, then let your arms extend fully again.', ['pull'], ['back', 'biceps'], 'weightlifting', 2],
  ['Machine row', 'Seated row machine with a chest pad. Adjust the seat so the handles are at chest height, sit with your chest against the pad and grip the handles. Pull them toward you by driving your elbows back, squeeze for a second, then return slowly.', ['pull'], ['back', 'biceps'], 'weightlifting', 2],
  ['Meadows row', 'Landmine (a barbell with one end anchored in a floor sleeve or corner). Stand side-on to the bar with your feet staggered, hinge forward and grip the end of the bar with the hand furthest from it. Row the bar up toward your hip with your elbow out to the side, then lower slowly.', ['pull'], ['back', 'biceps'], 'weightlifting', 2],
  ['Lat pulldown', 'Lat pulldown machine with the wide bar. Sit with your thighs under the pads, grip the bar wider than shoulder width and lean back slightly. Pull the bar down to your upper chest, driving your elbows down and back, then let it rise slowly until your arms are straight.', ['pull'], ['back', 'biceps'], 'weightlifting', 2],
  ['Close-grip lat pulldown', 'Lat pulldown machine with the narrow V-handle. Sit with your thighs under the pads, hold the handle with palms facing each other, and lean back slightly. Pull the handle down to your chest, keeping your chest tall, then let it rise slowly.', ['pull'], ['back', 'biceps'], 'weightlifting', 2],
  ['Straight-arm pulldown', 'Cable machine with a straight bar or rope on the high pulley. Stand facing it, hold the bar with arms almost straight and hinge forward slightly. Keeping your arms nearly straight, sweep the bar down in an arc until it touches your thighs, then let it rise. You should feel this in the sides of your back.', ['pull'], ['back'], 'weightlifting', 3],
  ['Dumbbell pullover', 'One dumbbell and a flat bench. Lie across the bench with only your upper back on it and feet flat on the floor. Hold the dumbbell over your chest with both hands, then lower it back behind your head in an arc with a slight elbow bend. Pull it back over your chest.', ['pull'], ['back', 'chest'], 'weightlifting', 3],
  ['Barbell shrug', 'Barbell. Stand tall holding the bar in front of your thighs with straight arms. Lift your shoulders straight up toward your ears as high as you can, hold for a second, then lower slowly. Do not roll the shoulders forward or back.', ['pull'], ['back', 'shoulders'], 'weightlifting', 3],
  ['Dumbbell shrug', 'Two dumbbells. Stand tall with a dumbbell in each hand at your sides. Lift your shoulders straight up toward your ears, pause at the top, then lower slowly. Keep your arms straight the whole time.', ['pull'], ['back', 'shoulders'], 'weightlifting', 3],

  // ---------------- SHOULDERS ----------------
  ['Overhead press', 'Barbell in a rack set at shoulder height. Grip the bar just outside shoulder width, step back with it resting on the front of your shoulders. Brace your stomach, press the bar straight up over your head and move your head slightly forward once the bar passes it. Lower it back to your shoulders with control.', ['push'], ['shoulders', 'triceps'], 'weightlifting', 1],
  ['Push press', 'Barbell at shoulder height. Hold the bar on the front of your shoulders, then bend your knees slightly and drive up quickly with your legs to start the bar moving. Finish by pressing it overhead with your arms. Lower with control. The leg drive lets you use more weight than a strict press.', ['push', 'full-body'], ['shoulders', 'triceps', 'quads'], 'weightlifting', 1],
  ['Seated dumbbell shoulder press', 'Two dumbbells and an upright bench. Sit with your back against the pad and hold the dumbbells at ear height with palms facing forward. Press them up until your arms are straight, without banging them together, then lower slowly back to ear height.', ['push'], ['shoulders', 'triceps'], 'weightlifting', 2],
  ['Arnold press', 'Two dumbbells and an upright bench. Sit holding the dumbbells in front of your shoulders with palms facing you. As you press up, rotate your hands so your palms face forward at the top. Reverse the twist on the way down.', ['push'], ['shoulders', 'triceps'], 'weightlifting', 2],
  ['Machine shoulder press', 'Seated shoulder press machine. Adjust the seat so the handles start level with your ears. Sit with your back against the pad, grip the handles and press up until your arms are nearly straight, then lower slowly. Do not lock your elbows out hard at the top.', ['push'], ['shoulders', 'triceps'], 'weightlifting', 2],
  ['Landmine press', 'Landmine (a barbell with one end anchored on the floor). Kneel on one knee or stand facing the bar, hold the free end with one hand at your shoulder. Press it up and forward until your arm is straight, then lower back to your shoulder. Keep your stomach braced.', ['push'], ['shoulders', 'chest', 'triceps'], 'weightlifting', 2],
  ['Upright row', 'Barbell or EZ-bar. Stand holding the bar in front of your thighs with a grip wider than shoulder width. Pull it straight up to your lower chest, leading with your elbows and keeping the bar close to your body, then lower slowly. Stop if you feel pinching in the shoulders.', ['pull'], ['shoulders', 'back'], 'weightlifting', 2],
  ['Dumbbell lateral raise', 'Two light dumbbells. Stand with a dumbbell in each hand at your sides and a slight forward lean. Raise your arms out to the sides until they reach shoulder height, leading with your elbows, then lower slowly. Keep a small bend in the elbows and do not swing.', ['push'], ['shoulders'], 'weightlifting', 3],
  ['Cable lateral raise', 'Cable machine with the pulley set low and a single handle. Stand side-on with the cable running behind your body, hold the handle in the hand furthest from the machine. Raise your arm out to the side to shoulder height, then lower slowly. The cable keeps tension the whole way.', ['push'], ['shoulders'], 'weightlifting', 3],
  ['Machine lateral raise', 'Lateral raise machine. Sit with the pads resting against the outside of your upper arms or elbows. Raise your arms out to the sides until they are level with your shoulders, pause, then lower slowly.', ['push'], ['shoulders'], 'weightlifting', 3],
  ['Dumbbell front raise', 'Two light dumbbells. Stand holding them in front of your thighs. Raise one arm straight out in front of you until it reaches eye level, lower it slowly, then repeat with the other arm. Keep your body still and your thumbs pointing slightly up.', ['push'], ['shoulders'], 'weightlifting', 3],
  ['Rear delt fly', 'Two light dumbbells. Hinge forward at the hips until your torso is nearly parallel to the floor, letting the dumbbells hang below you. With a slight bend in your elbows, raise your arms out to the sides until they are level with your back, squeeze the backs of your shoulders, then lower slowly.', ['pull'], ['shoulders', 'back'], 'weightlifting', 3],
  ['Reverse pec deck', 'Pec deck machine set for the reverse movement (handles at the front). Sit facing the pad with the handles at shoulder height. Sweep your arms out and back until your hands are level with your shoulders, pause, then return slowly. Do not shrug.', ['pull'], ['shoulders', 'back'], 'weightlifting', 3],
  ['Face pull', 'Cable machine with a rope attachment set at face height. Hold the rope with both hands, palms facing each other, and step back. Pull the rope toward your eyes, splitting your hands apart and keeping your elbows high, then let it return slowly.', ['pull'], ['shoulders', 'back'], 'weightlifting', 3],

  // ---------------- BICEPS ----------------
  ['Barbell curl', 'Barbell. Stand holding the bar in front of your thighs with palms facing forward, hands shoulder width apart. Keeping your elbows pinned to your sides, curl the bar up to your shoulders, then lower it slowly over about three seconds. Do not swing your body.', ['pull'], ['biceps'], 'weightlifting', 2],
  ['EZ-bar curl', 'EZ-bar (the bar with the zigzag shape). Hold it on the angled parts so your wrists are turned slightly inward. Keeping your elbows at your sides, curl the bar up to your shoulders, then lower slowly all the way down. The angled grip is easier on the wrists than a straight bar.', ['pull'], ['biceps'], 'weightlifting', 2],
  ['Dumbbell curl', 'Two dumbbells. Stand with a dumbbell in each hand at your sides, palms facing forward. Curl one or both up to your shoulders, turning your palm up as you lift, and squeeze at the top. Lower slowly. Keep your elbows still at your sides.', ['pull'], ['biceps'], 'weightlifting', 3],
  ['Hammer curl', 'Two dumbbells. Stand holding them at your sides with palms facing each other, like holding a hammer. Keeping that grip, curl the dumbbells up to your shoulders, then lower slowly. Works the outer biceps and forearms.', ['pull'], ['biceps'], 'weightlifting', 3],
  ['Incline dumbbell curl', 'Two dumbbells and a bench set to about 45 degrees. Sit back on the bench and let your arms hang straight down and slightly behind you. Curl the dumbbells up without moving your upper arms, then lower slowly. You should feel a deep stretch at the bottom.', ['pull'], ['biceps'], 'weightlifting', 3],
  ['Preacher curl', 'Preacher curl bench with a barbell, EZ-bar or dumbbell. Sit with your upper arms flat on the sloped pad and your armpits over the top edge. Curl the weight up toward your shoulders, then lower slowly. Do not fully straighten your arms at the bottom.', ['pull'], ['biceps'], 'weightlifting', 3],
  ['Concentration curl', 'One dumbbell and a bench. Sit with your feet wide, lean forward and brace the back of your upper arm against the inside of your thigh. Curl the dumbbell up toward your shoulder, pause, then lower slowly. Switch arms.', ['pull'], ['biceps'], 'weightlifting', 3],
  ['Cable curl', 'Cable machine with the pulley set low and a straight bar or EZ-bar attachment. Stand facing the machine holding the bar with palms up. Curl it to your shoulders, keeping your elbows in front of your hips, then lower slowly. The cable keeps tension all the way through.', ['pull'], ['biceps'], 'weightlifting', 3],
  ['Bayesian cable curl', 'Cable machine with the pulley set low and a single handle. Face away from the machine, hold the handle with one hand and take a step forward so your arm is pulled slightly behind you. Curl the handle up to your shoulder, then lower slowly. Big stretch at the bottom.', ['pull'], ['biceps'], 'weightlifting', 3],
  ['Spider curl', 'Two dumbbells and a bench set to about 45 degrees. Lie face down with your chest on the pad and arms hanging straight down. Curl the dumbbells up toward your shoulders and squeeze hard at the top, then lower slowly.', ['pull'], ['biceps'], 'weightlifting', 3],
  ['Reverse curl', 'Barbell or EZ-bar. Hold the bar in front of your thighs with palms facing down. Curl it up to your shoulders, keeping your elbows at your sides, then lower slowly. Works the forearms and the outer part of the biceps.', ['pull'], ['biceps'], 'weightlifting', 3],
  ['Zottman curl', 'Two dumbbells. Stand with the dumbbells at your sides, palms facing forward. Curl them up to your shoulders, then at the top rotate your hands so your palms face down. Lower slowly with palms down, then rotate back at the bottom.', ['pull'], ['biceps'], 'weightlifting', 3],
  ['Machine bicep curl', 'Bicep curl machine. Sit with your upper arms resting on the pad and grip the handles. Curl the handles up toward your shoulders through the full range, then let them return slowly.', ['pull'], ['biceps'], 'weightlifting', 3],

  // ---------------- TRICEPS ----------------
  ['Close-grip bench press', 'Barbell on a flat bench. Lie back and grip the bar with your hands about shoulder width apart, narrower than a normal bench press. Lower the bar to your lower chest keeping your elbows tucked close to your body, then press back up. Works the triceps more than the chest.', ['push'], ['triceps', 'chest'], 'weightlifting', 2],
  ['JM press', 'Barbell on a flat bench. Grip the bar at shoulder width and hold it above your chest. Lower it by bending your elbows and letting them travel forward, so the bar comes down toward your chin, then press back up. A cross between a close-grip press and a skull crusher.', ['push'], ['triceps'], 'weightlifting', 2],
  ['Skull crusher', 'EZ-bar and a flat bench. Lie back holding the bar above your chest with straight arms. Keeping your upper arms still and pointing to the ceiling, bend your elbows to lower the bar toward your forehead, then straighten your arms to lift it back up.', ['push'], ['triceps'], 'weightlifting', 3],
  ['Overhead dumbbell triceps extension', 'One dumbbell. Stand or sit holding the dumbbell with both hands, arms straight up over your head. Keeping your elbows close to your head, bend them to lower the dumbbell behind your neck, then straighten your arms to lift it back up.', ['push'], ['triceps'], 'weightlifting', 3],
  ['Cable overhead triceps extension', 'Cable machine with a rope attachment on the low pulley. Hold the rope, turn to face away from the machine and lift your hands overhead with elbows bent. Straighten your arms to push the rope up and forward, then lower slowly behind your head.', ['push'], ['triceps'], 'weightlifting', 3],
  ['Rope triceps pushdown', 'Cable machine with a rope attachment on the high pulley. Stand facing it holding the rope with elbows bent at your sides. Push your hands down until your arms are straight, splitting the rope apart at the bottom, then let it rise slowly. Keep your elbows pinned to your sides.', ['push'], ['triceps'], 'weightlifting', 3],
  ['Straight-bar triceps pushdown', 'Cable machine with a straight bar on the high pulley. Hold the bar with palms down, elbows bent and tucked to your sides. Push the bar down until your arms are fully straight, then let it rise slowly. Do not let your elbows drift forward.', ['push'], ['triceps'], 'weightlifting', 3],
  ['Single-arm cable pushdown', 'Cable machine with a single handle on the high pulley. Hold the handle in one hand with your elbow at your side. Push down until your arm is straight, then let it rise slowly. Works one arm at a time. Switch hands.', ['push'], ['triceps'], 'weightlifting', 3],
  ['Dumbbell kickback', 'One light dumbbell and a bench. Place your free hand and knee on the bench and hinge forward with a flat back. Hold the dumbbell with your upper arm tucked to your side and parallel to the floor. Straighten your arm fully behind you, squeeze, then bend it back.', ['push'], ['triceps'], 'weightlifting', 3],
  ['Tate press', 'Two dumbbells and a flat bench. Lie back with the dumbbells above your chest, palms facing your feet and elbows out to the sides. Bend your elbows to lower the dumbbells inward until they touch your chest, then press back up.', ['push'], ['triceps'], 'weightlifting', 3],
  ['Machine triceps extension', 'Triceps extension machine. Sit with your elbows resting on the pad and grip the handles. Straighten your arms fully to push the handles down, then let them return slowly.', ['push'], ['triceps'], 'weightlifting', 3],

  // ---------------- QUADS ----------------
  ['Barbell back squat', 'Barbell in a squat rack set at about chest height. Step under the bar so it rests across your upper back, grip it wider than your shoulders and stand up to unrack. Step back, feet shoulder width apart. Brace your stomach, sit down and back as if into a chair until your thighs are at least parallel to the floor, then push through your whole foot to stand up. Keep your knees tracking over your toes.', ['legs'], ['quads', 'glutes', 'hamstrings'], 'weightlifting', 1],
  ['Front squat', 'Barbell in a squat rack. Rest the bar on the front of your shoulders with your elbows pointing forward and high, fingers under the bar. Stand up to unrack, step back, then squat straight down keeping your chest up and elbows high. Stand back up. Stays more upright than a back squat.', ['legs'], ['quads', 'glutes'], 'weightlifting', 1],
  ['Safety bar squat', 'Safety squat bar (the padded bar with handles that point forward) in a rack. Rest it on your shoulders and hold the handles. Unrack, step back and squat down to at least parallel, staying tall against the bar\'s forward pull, then stand up.', ['legs'], ['quads', 'glutes'], 'weightlifting', 1],
  ['Box squat', 'Barbell in a squat rack and a box or bench behind you at about knee height. Unrack the bar on your upper back, step back so the box is behind you. Sit back onto the box under control, pause for a moment without relaxing, then drive up to standing.', ['legs'], ['quads', 'glutes', 'hamstrings'], 'weightlifting', 1],
  ['Hack squat', 'Hack squat machine. Stand on the platform with your back and shoulders against the pads, feet about shoulder width in the middle of the platform. Release the safety handles, lower yourself by bending your knees until your thighs pass parallel, then push through your whole foot to come back up.', ['legs'], ['quads', 'glutes'], 'weightlifting', 2],
  ['Leg press', 'Leg press machine. Sit with your back against the pad and place your feet on the platform about shoulder width apart. Release the safety handles, lower the platform by bending your knees until they are near your chest, then push it back up. Do not lock your knees out at the top and keep your lower back on the seat.', ['legs'], ['quads', 'glutes'], 'weightlifting', 2],
  ['Pendulum squat', 'Pendulum squat machine. Stand on the platform with your shoulders under the pads and your back against the support. Lower yourself into a deep squat, staying upright against the pad, then push through your heels to come back up.', ['legs'], ['quads', 'glutes'], 'weightlifting', 2],
  ['Smith machine squat', 'Smith machine (the bar that runs on fixed rails). Place the bar on your upper back and set your feet slightly in front of the bar. Unhook it, squat straight down until your thighs are parallel, then push back up and re-hook at the end. The rails let your feet sit further forward than a free squat.', ['legs'], ['quads', 'glutes'], 'weightlifting', 2],
  ['Zercher squat', 'Barbell in a rack set at about elbow height. Hold the bar in the crook of your elbows against your body, with your hands clasped. Step back and squat down, letting the bar pass between your knees, then stand up. Keep your torso upright.', ['legs'], ['quads', 'glutes'], 'weightlifting', 2],
  ['Goblet squat', 'One dumbbell or kettlebell. Hold it against your chest with both hands, elbows pointing down. Stand with feet shoulder width apart and squat down until your elbows touch the inside of your knees, keeping your chest up, then stand back up.', ['legs'], ['quads', 'glutes'], 'weightlifting', 2],
  ['Bulgarian split squat', 'Two dumbbells and a bench. Stand facing away from the bench and rest the top of one foot on it behind you. Holding a dumbbell in each hand, lower straight down until your front thigh is parallel to the floor, then push through your front foot to stand. Switch legs.', ['legs'], ['quads', 'glutes'], 'weightlifting', 2],
  ['Walking lunge', 'Two dumbbells. Hold one in each hand at your sides. Take a long step forward and lower until your back knee is just above the floor and your front thigh is parallel. Push off your front heel to stand and step straight into the next lunge with the other leg.', ['legs'], ['quads', 'glutes', 'hamstrings'], 'weightlifting', 2],
  ['Reverse lunge', 'Two dumbbells or body weight. Stand tall, then step one foot back and lower until your back knee is just above the floor. Push through your front foot to return to standing. Stepping backward is kinder on the knees than stepping forward.', ['legs'], ['quads', 'glutes'], 'weightlifting', 2],
  ['Step-up', 'A box or bench at about knee height, plus dumbbells if wanted. Place one whole foot on the box and push through that foot to stand on top, without pushing off the floor with your back leg. Step down slowly with the same leg. Switch legs.', ['legs'], ['quads', 'glutes'], 'weightlifting', 2],
  ['Leg extension', 'Leg extension machine. Sit with your back against the pad and the roller resting on the front of your lower shins. Straighten your legs fully, squeeze the front of your thighs for a second, then lower slowly.', ['legs'], ['quads'], 'weightlifting', 3],
  ['Sissy squat', 'Body weight, holding a post or rack for balance, or a sissy squat machine. Rise onto the balls of your feet, then lean your body back while bending your knees forward, keeping your hips straight. Lower as far as you can control, then pull back up. Deep stretch in the front of the thighs.', ['legs'], ['quads'], 'weightlifting', 3],

  // ---------------- HAMSTRINGS ----------------
  ['Romanian deadlift', 'Barbell held in front of your thighs. Stand tall with a slight bend in your knees. Push your hips backward and let the bar slide down the front of your legs, keeping your back flat and the bar close. Stop when you feel a strong stretch in the backs of your thighs, then squeeze your glutes to stand tall again.', ['legs', 'pull'], ['hamstrings', 'glutes', 'back'], 'weightlifting', 1],
  ['Stiff-leg deadlift', 'Barbell held in front of your thighs. Stand with your legs almost straight. Hinge at the hips to lower the bar toward mid shin, keeping your back flat and the bar close to your legs, then stand back up. Straighter legs than a Romanian deadlift means more stretch in the hamstrings.', ['legs', 'pull'], ['hamstrings', 'glutes', 'back'], 'weightlifting', 1],
  ['Dumbbell Romanian deadlift', 'Two dumbbells held in front of your thighs. Stand tall with a slight bend in your knees. Push your hips back and lower the dumbbells down the front of your legs with a flat back until you feel a stretch in the backs of your thighs, then squeeze your glutes to stand up.', ['legs'], ['hamstrings', 'glutes'], 'weightlifting', 2],
  ['Single-leg Romanian deadlift', 'One dumbbell or body weight. Stand on one leg, holding the dumbbell in the opposite hand. Hinge forward at the hip, letting your free leg extend straight out behind you, until your torso is nearly parallel to the floor. Keep your hips level, then return to standing. Switch legs.', ['legs'], ['hamstrings', 'glutes'], 'weightlifting', 2],
  ['Good morning', 'Barbell across your upper back, as in a back squat. Stand with a slight bend in your knees. Push your hips back and hinge forward until your torso is nearly parallel to the floor, keeping your back flat, then stand back up. Start light: this is hard on the lower back if rushed.', ['legs'], ['hamstrings', 'glutes', 'back'], 'weightlifting', 2],
  ['Glute-ham raise', 'Glute-ham raise machine. Kneel with your knees on the pad and your ankles hooked under the rollers. Starting upright, lower your torso forward as slowly as you can, then pull yourself back up using your hamstrings. Use your hands on the pad to help if needed.', ['legs'], ['hamstrings', 'glutes'], 'weightlifting', 2],
  ['Lying leg curl', 'Lying leg curl machine. Lie face down with the roller pad just above your heels and your hips pressed into the bench. Curl your heels up toward your glutes, squeeze, then lower slowly over about three seconds.', ['legs'], ['hamstrings'], 'weightlifting', 3],
  ['Seated leg curl', 'Seated leg curl machine. Sit with your back against the pad, the thigh pad locked down over your legs and the roller on the back of your lower calves. Curl your heels down and under the seat as far as you can, then let them return slowly.', ['legs'], ['hamstrings'], 'weightlifting', 3],
  ['Standing single-leg curl', 'Standing leg curl machine, or a cable with an ankle strap. Stand with the roller or strap behind one ankle and hold the machine for balance. Curl your heel up toward your glute, squeeze, then lower slowly. Switch legs.', ['legs'], ['hamstrings'], 'weightlifting', 3],
  ['45-degree back extension', '45-degree back extension bench. Set the pad so it sits just below your hip bones and hook your heels under the rollers. Cross your arms or hold a plate at your chest, hinge down at the hips, then rise until your body forms a straight line. Squeeze your glutes at the top, do not arch past straight.', ['legs'], ['hamstrings', 'glutes', 'back'], 'weightlifting', 3],

  // ---------------- GLUTES ----------------
  ['Barbell hip thrust', 'Barbell and a bench. Sit on the floor with your upper back against the bench and the bar across your hips (a pad on the bar helps). Plant your feet flat, then drive your hips up until your body is flat from shoulders to knees. Squeeze your glutes at the top, keeping your chin tucked, then lower.', ['legs'], ['glutes', 'hamstrings'], 'weightlifting', 1],
  ['Machine hip thrust', 'Hip thrust machine. Sit with your upper back against the pad and the belt or pad across your hips, feet flat on the platform. Drive your hips up until your body is straight from shoulders to knees, squeeze your glutes for a full second, then lower.', ['legs'], ['glutes', 'hamstrings'], 'weightlifting', 2],
  ['Barbell glute bridge', 'Barbell, lying on the floor. Lie on your back with knees bent, feet flat and the bar resting across your hips. Push through your heels to lift your hips until your body is straight from shoulders to knees, squeeze your glutes, then lower.', ['legs'], ['glutes', 'hamstrings'], 'weightlifting', 2],
  ['Kettlebell swing', 'One kettlebell. Stand with feet slightly wider than shoulder width and the kettlebell on the floor in front of you. Hinge at the hips, grab it with both hands and swing it back between your legs. Snap your hips forward to swing it up to chest height, then let it swing back between your legs. It is a hip hinge, not a squat.', ['legs', 'full-body'], ['glutes', 'hamstrings', 'back'], 'weightlifting', 2],
  ['Curtsy lunge', 'Two dumbbells or body weight. Stand tall, then step one foot back and across behind your other leg, as if curtsying. Lower until your front thigh is near parallel, then push through your front foot to stand. Switch legs.', ['legs'], ['glutes', 'quads'], 'weightlifting', 2],
  ['Cable pull-through', 'Cable machine with a rope attachment on the low pulley. Face away from the machine with the rope between your legs, holding it with both hands. Walk forward a step, hinge at the hips letting the rope pull back, then snap your hips forward to stand tall and squeeze your glutes.', ['legs'], ['glutes', 'hamstrings'], 'weightlifting', 3],
  ['Cable glute kickback', 'Cable machine with an ankle strap on the low pulley. Strap one ankle, face the machine and hold it for balance with a slight forward lean. Kick that leg straight back and up, squeeze your glute, then return slowly. Switch legs.', ['legs'], ['glutes'], 'weightlifting', 3],
  ['Hip abduction machine', 'Hip abduction machine. Sit with the pads against the outside of your knees. Push your knees apart as far as you can, pause, then let them come back together slowly. Leaning forward slightly targets the glutes more.', ['legs'], ['glutes'], 'weightlifting', 3],
  ['Reverse hyperextension', 'Reverse hyper machine, or a high bench. Lie face down with your hips on the edge of the pad and your legs hanging. Hold the handles, then swing your legs up behind you until they are level with your body using your glutes, and lower slowly. Do not arch your lower back.', ['legs'], ['glutes', 'hamstrings'], 'weightlifting', 3],
  ['Frog pump', 'Body weight or a dumbbell on your hips, lying on the floor. Lie on your back, press the soles of your feet together and let your knees fall out to the sides. Pump your hips up and down in a short, quick range, squeezing your glutes each time. Best done for high reps.', ['legs'], ['glutes'], 'weightlifting', 3],
  ['Farmer\'s carry', 'Two heavy dumbbells or kettlebells. Pick one up in each hand, stand tall with your shoulders back and stomach braced. Walk forward with short, quick steps for a set distance or time, then set the weights down carefully. Do not let your shoulders slump.', ['full-body', 'core'], ['abs', 'back', 'shoulders'], 'weightlifting', 2],

  // ---------------- CALVES ----------------
  ['Standing calf raise', 'Standing calf raise machine, or a step with a barbell or dumbbells. Stand with the balls of your feet on the edge and heels hanging down. Lower your heels as far as they go for a full stretch, pause, then rise up onto your toes as high as you can and hold for a second.', ['legs'], ['calves'], 'weightlifting', 3],
  ['Seated calf raise', 'Seated calf raise machine. Sit with the pad resting on your lower thighs and the balls of your feet on the platform. Lower your heels for a deep stretch, then push up onto your toes as high as possible. Works the lower part of the calf.', ['legs'], ['calves'], 'weightlifting', 3],
  ['Leg press calf raise', 'Leg press machine. Sit as for a leg press but place only the balls of your feet on the bottom edge of the platform, legs straight. Let the platform push your toes toward you for a stretch, then push it away by pointing your toes. Keep your knees straight but not locked.', ['legs'], ['calves'], 'weightlifting', 3],
  ['Donkey calf raise', 'Donkey calf raise machine, or a step while bent forward with a partner or pad on your hips. Bend forward at the hips with your hands on a support and the balls of your feet on the edge. Lower your heels fully, then rise up onto your toes.', ['legs'], ['calves'], 'weightlifting', 3],
  ['Single-leg dumbbell calf raise', 'One dumbbell and a step. Stand on one foot with the ball of that foot on the edge of the step, holding the dumbbell in the same-side hand and a wall or rail with the other. Lower your heel for a stretch, then rise onto your toes slowly. Switch legs.', ['legs'], ['calves'], 'weightlifting', 3],
  ['Smith machine calf raise', 'Smith machine and a block or plate to stand on. Rest the bar on your upper back, place the balls of your feet on the block with heels hanging off. Rise up onto your toes as high as you can, pause, then lower for a full stretch.', ['legs'], ['calves'], 'weightlifting', 3],

  // ---------------- ABS (weighted) ----------------
  ['Cable crunch', 'Cable machine with a rope attachment on the high pulley. Kneel facing the machine holding the rope beside your head. Keeping your hips still, curl your torso down and bring your elbows toward your knees, then rise back up slowly. The movement comes from your stomach, not your arms.', ['core'], ['abs'], 'weightlifting', 3],
  ['Machine crunch', 'Ab crunch machine. Sit with your back against the pad and hold the handles or rest your chest on the pad. Curl your torso forward and down, squeezing your stomach, then return slowly.', ['core'], ['abs'], 'weightlifting', 3],
  ['Weighted decline sit-up', 'Decline bench and a weight plate. Hook your feet under the pads, hold the plate against your chest and lie back. Curl up to sitting, then lower yourself slowly. Do not pull on your neck.', ['core'], ['abs'], 'weightlifting', 3],
  ['Weighted plank', 'Weight plate and a partner to place it on your upper back, or a weighted vest. Get into a forearm plank with your body in a straight line from head to heels, squeeze your glutes and hold, breathing normally.', ['core'], ['abs'], 'weightlifting', 3],
  ['Pallof press', 'Cable machine with a single handle set at chest height. Stand side-on to the machine, hold the handle with both hands at your chest. Press your arms straight out in front of you and hold, resisting the cable\'s pull to twist you, then bring your hands back. Switch sides.', ['core'], ['abs'], 'weightlifting', 3],
  ['Cable woodchop', 'Cable machine with a single handle set high. Stand side-on, hold the handle with both hands above one shoulder. Pull it down and across your body to the opposite hip, rotating your hips and shoulders, then return slowly. Keep your arms fairly straight. Switch sides.', ['core'], ['abs'], 'weightlifting', 3],
  ['Landmine rotation', 'Landmine (a barbell with one end anchored on the floor). Stand facing the bar, hold the free end with both hands and straight arms at chest height. Sweep it in an arc from one hip to the other, pivoting your feet, keeping your arms straight.', ['core'], ['abs'], 'weightlifting', 3],
  ['Dumbbell side bend', 'One dumbbell. Stand tall holding it in one hand at your side. Bend sideways toward that hand, letting the dumbbell slide down your leg, then pull yourself back upright using the muscles on the other side. Do not lean forward. Switch sides.', ['core'], ['abs'], 'weightlifting', 3],
  ['Weighted Russian twist', 'Weight plate or dumbbell. Sit on the floor with knees bent, lean back slightly and lift your feet if you can. Hold the weight in front of your chest and rotate your torso to tap it on the floor beside each hip, keeping your movements controlled.', ['core'], ['abs'], 'weightlifting', 3],

  // ---------------- CALISTHENICS ----------------
  ['Pull-up', 'Pull-up bar. Hang from the bar with your palms facing away and hands a little wider than shoulder width, arms fully straight. Pull yourself up until your chin is above the bar, then lower yourself slowly all the way back to a straight-arm hang.', ['pull'], ['back', 'biceps'], 'calisthenics', 1],
  ['Chin-up', 'Pull-up bar. Hang with your palms facing toward you and hands about shoulder width apart. Pull up until your chin clears the bar, then lower slowly to straight arms. Uses more biceps than a pull-up.', ['pull'], ['back', 'biceps'], 'calisthenics', 1],
  ['Inverted row', 'A bar set at about hip height in a rack, or a Smith machine bar. Lie underneath it, grip it and hang with your body straight and heels on the floor. Pull your chest up to the bar, then lower slowly. Raise your feet onto a box to make it harder.', ['pull'], ['back', 'biceps'], 'calisthenics', 2],
  ['Dead hang', 'Pull-up bar. Hang from the bar with straight arms and your shoulders pulled slightly down away from your ears. Hold for time, breathing normally. Builds grip strength and stretches the sides of your back.', ['pull'], ['back'], 'calisthenics', 3],
  ['Push-up', 'Body weight. Start in a straight line from head to heels with your hands under your shoulders. Lower your chest to the floor with your elbows at about 45 degrees to your body, then push back up. Keep your hips from sagging.', ['push'], ['chest', 'triceps', 'shoulders'], 'calisthenics', 2],
  ['Diamond push-up', 'Body weight. Get into a push-up position with your hands together under your chest, thumbs and index fingers touching to make a diamond shape. Lower your chest to your hands keeping your elbows tucked in, then push up. Hard on the triceps.', ['push'], ['triceps', 'chest'], 'calisthenics', 3],
  ['Pike push-up', 'Body weight. Start in a push-up position, then walk your feet in and push your hips up so your body makes an upside-down V. Bend your elbows to lower the top of your head toward the floor, then press back up. Targets the shoulders.', ['push'], ['shoulders', 'triceps'], 'calisthenics', 2],
  ['Handstand push-up', 'A wall. Kick up into a handstand with your heels resting against the wall and hands shoulder width apart. Bend your elbows to lower your head to the floor or a pad, then press back up to straight arms. Advanced: build up with pike push-ups first.', ['push'], ['shoulders', 'triceps'], 'calisthenics', 1],
  ['Dip', 'Parallel dip bars. Support yourself on straight arms, then bend your elbows to lower until your upper arms are parallel to the floor. Press back up. Lean forward to work the chest more, stay upright for the triceps.', ['push'], ['chest', 'triceps', 'shoulders'], 'calisthenics', 1],
  ['Bench dip', 'A bench or sturdy chair. Sit on the edge with your hands beside your hips gripping the edge, then walk your feet forward and slide your hips off. Bend your elbows to lower your body until they reach about 90 degrees, then press back up.', ['push'], ['triceps'], 'calisthenics', 3],
  ['Bodyweight squat', 'Body weight. Stand with feet shoulder width apart and toes slightly out. Sit down and back until your thighs are at least parallel to the floor, keeping your chest up and heels down, then stand back up.', ['legs'], ['quads', 'glutes'], 'calisthenics', 2],
  ['Pistol squat', 'Body weight, holding a post or door frame for balance if needed. Stand on one leg with the other leg held straight out in front. Sit all the way down on the standing leg, then stand back up. Advanced: build up with box squats on one leg.', ['legs'], ['quads', 'glutes'], 'calisthenics', 1],
  ['Bodyweight lunge', 'Body weight. Stand tall, take a big step forward and lower until your back knee is just above the floor and your front thigh is parallel. Push through your front foot to step back to standing. Switch legs.', ['legs'], ['quads', 'glutes'], 'calisthenics', 2],
  ['Nordic hamstring curl', 'Something to anchor your ankles: a partner, a loaded barbell or a padded bar. Kneel with your ankles held down and your body upright. Lower your torso forward as slowly as you can, using your hamstrings to resist, catch yourself with your hands, then push back up.', ['legs'], ['hamstrings'], 'calisthenics', 2],
  ['Bodyweight glute bridge', 'Body weight, lying on the floor. Lie on your back with knees bent and feet flat, close to your hips. Push through your heels to lift your hips until your body is straight from shoulders to knees, squeeze your glutes, then lower.', ['legs'], ['glutes', 'hamstrings'], 'calisthenics', 3],
  ['Single-leg glute bridge', 'Body weight, lying on the floor. Lie on your back with one foot flat and the other leg extended straight. Drive through the planted foot to lift your hips until straight, without letting them tilt to one side, then lower. Switch legs.', ['legs'], ['glutes', 'hamstrings'], 'calisthenics', 3],
  ['Hanging leg raise', 'Pull-up bar. Hang with straight arms, then raise your straight legs in front of you until they are at least level with your hips. Lower slowly without swinging. Bend your knees to make it easier.', ['core'], ['abs'], 'calisthenics', 2],
  ['Hanging knee raise', 'Pull-up bar. Hang with straight arms, then pull your knees up toward your chest, curling your hips forward at the top. Lower slowly without swinging.', ['core'], ['abs'], 'calisthenics', 3],
  ['Ab wheel rollout', 'Ab wheel. Kneel on a mat holding the wheel on the floor in front of you. Roll it forward, extending your body as far as you can while keeping your back flat and stomach tight. Pull back to the start using your abs.', ['core'], ['abs'], 'calisthenics', 2],
  ['Plank', 'Body weight. Rest on your forearms and toes with your body in a straight line from head to heels. Squeeze your glutes, keep your stomach tight and hold for time, breathing normally.', ['core'], ['abs'], 'calisthenics', 3],
  ['Side plank', 'Body weight. Lie on one side, then lift up onto your forearm and the side of your foot so your body forms a straight line, hips stacked and lifted. Hold for time, then switch sides.', ['core'], ['abs'], 'calisthenics', 3],
  ['Hollow body hold', 'Body weight, lying on the floor. Lie on your back, press your lower back into the floor, then lift your shoulders and straight legs a few inches off the floor with arms extended overhead. Hold, keeping your lower back flat.', ['core'], ['abs'], 'calisthenics', 3],
  ['Dead bug', 'Body weight, lying on the floor. Lie on your back with arms pointing to the ceiling and knees bent above your hips. Slowly lower one arm overhead and the opposite leg toward the floor while keeping your lower back pressed down, then return and switch sides.', ['core'], ['abs'], 'calisthenics', 3],
  ['Mountain climber', 'Body weight. Start in a push-up position. Drive one knee in toward your chest, then quickly switch legs, keeping your hips level and your hands under your shoulders. Continue alternating at pace.', ['core', 'full-body'], ['abs', 'quads'], 'calisthenics', 3],
  ['Burpee', 'Body weight. From standing, drop your hands to the floor, jump your feet back into a push-up position, do a push-up, jump your feet back in, then jump up with arms overhead. Keep a steady rhythm.', ['full-body'], ['quads', 'chest', 'abs'], 'calisthenics', 2],
  ['Superman', 'Body weight, lying on the floor. Lie face down with arms extended in front of you. Lift your arms, chest and legs off the floor at the same time, hold briefly, then lower.', ['core'], ['back', 'glutes'], 'calisthenics', 3],

  // ---------------- CARDIO ----------------
  ['Treadmill run', 'Treadmill. Start at a walk, then increase the speed to a run you could hold a short conversation at. Either keep a steady pace for the whole time, or alternate one minute hard with one minute easy for intervals.', ['full-body'], ['quads', 'hamstrings', 'calves'], 'cardio', 2],
  ['Incline treadmill walk', 'Treadmill. Set the incline high (10 to 15 percent) and walk briskly without holding the rails. Works the glutes and calves harder than flat walking with much less impact than running.', ['legs'], ['glutes', 'calves', 'hamstrings'], 'cardio', 3],
  ['Rowing machine', 'Rowing machine. Strap your feet in and grip the handle. Push with your legs first, then lean your body back slightly, then pull the handle to your lower chest. Return in the reverse order: arms, body, then legs. Most of the power comes from your legs.', ['full-body', 'pull'], ['back', 'quads', 'glutes'], 'cardio', 2],
  ['Stationary bike', 'Exercise bike. Set the seat so your knee is slightly bent at the bottom of the pedal stroke. Pedal at a steady pace, or alternate hard and easy intervals. Keep your upper body relaxed.', ['legs'], ['quads', 'glutes'], 'cardio', 3],
  ['Assault bike', 'Air bike (the fan bike with moving handles). Pedal while pushing and pulling the handles at the same time. The harder you go, the more resistance the fan gives. Best for short, hard intervals.', ['full-body'], ['quads', 'shoulders', 'back'], 'cardio', 2],
  ['Stair climber', 'Stair climbing machine. Take full steps with your whole foot, keep your posture upright and rest your hands lightly on the rails rather than leaning on them.', ['legs'], ['glutes', 'quads', 'calves'], 'cardio', 3],
  ['Jump rope', 'Skipping rope. Hold a handle in each hand, elbows close to your sides, and turn the rope with your wrists rather than your arms. Make small hops on the balls of your feet with relaxed shoulders.', ['full-body'], ['calves'], 'cardio', 3],
  ['Sled push', 'Weighted sled. Load it, grip the upright poles with straight arms and lean into it. Drive forward with short, powerful steps for a set distance. Push, rest, repeat.', ['legs', 'full-body'], ['quads', 'glutes', 'calves'], 'cardio', 2],
  ['Elliptical', 'Elliptical or cross trainer. Stand on the pedals holding the moving handles. Push and pull the handles while pedalling in a smooth motion, keeping your heels down. Low impact on the knees.', ['full-body'], ['quads', 'glutes'], 'cardio', 3],

  // ---------------- MOBILITY ----------------
  ['Cat-cow', 'Mat, on hands and knees. Breathe in and drop your belly while lifting your head and tailbone (cow). Breathe out and round your spine up toward the ceiling, tucking your chin (cat). Move slowly, one breath per position.', ['core'], ['back', 'abs'], 'mobility', 3],
  ['World\'s greatest stretch', 'Mat or open floor. Step into a long lunge with your right foot forward and place your left hand on the floor. Put your right elbow down toward the inside of your right foot, then rotate and reach your right hand to the ceiling. Return, then rock your hips back to straighten the front leg. Switch sides.', ['full-body'], ['hamstrings', 'glutes', 'back'], 'mobility', 3],
  ['90/90 hip switch', 'Mat, sitting on the floor. Sit with one leg bent in front of you and the other bent out to the side, both knees at 90 degrees. Sit tall, then rotate both knees over to the other side without using your hands. Move slowly between the two positions.', ['legs'], ['glutes'], 'mobility', 3],
  ['Couch stretch', 'A wall or couch. Kneel with one knee on the floor against the wall and that shin running up the wall, with the other foot forward in a lunge. Squeeze the glute of the kneeling leg and stay upright. You should feel a stretch down the front of the kneeling thigh. Switch sides.', ['legs'], ['quads'], 'mobility', 3],
  ['Kneeling hip flexor stretch', 'Mat. Kneel on one knee with the other foot forward. Tuck your pelvis under (as if pulling your belt buckle up) and shift your weight gently forward until you feel a stretch at the front of the hip of the kneeling leg. Hold, then switch sides.', ['legs'], ['quads', 'glutes'], 'mobility', 3],
  ['Pigeon stretch', 'Mat. From hands and knees, bring one knee forward and lay that shin across in front of you, with the other leg stretched straight behind. Square your hips and fold your chest forward over the front leg. Hold, then switch sides.', ['legs'], ['glutes'], 'mobility', 3],
  ['Deep squat hold', 'Body weight. Squat all the way down with your feet flat and hold the bottom position. Push your knees out with your elbows and keep your chest up. Hold on to a post if your heels lift.', ['legs'], ['quads', 'glutes', 'calves'], 'mobility', 3],
  ['Ankle dorsiflexion rock', 'A wall. Kneel on one knee with the other foot forward, a hand\'s width from the wall. Rock forward, driving that knee toward the wall while keeping your heel down. Rock back and repeat. Switch sides.', ['legs'], ['calves'], 'mobility', 3],
  ['Standing hamstring stretch', 'A low box or step. Place one heel on it with that leg straight and toes pointing up. Keeping your back flat, hinge forward at the hips until you feel a stretch down the back of the thigh. Hold, then switch legs.', ['legs'], ['hamstrings'], 'mobility', 3],
  ['Thoracic rotation', 'Mat, on hands and knees. Place one hand behind your head. Rotate that elbow down toward the opposite wrist, then open it up and point it toward the ceiling, turning your upper back. Keep your hips still. Switch sides.', ['pull'], ['back'], 'mobility', 3],
  ['Band shoulder dislocates', 'A light resistance band or a broomstick. Hold it in front of you with a wide grip and straight arms. Lift it up over your head and continue behind you as far as you comfortably can, then bring it back over. Widen your grip if it feels tight.', ['push'], ['shoulders', 'chest'], 'mobility', 3],
  ['Wall slides', 'A wall. Stand with your back, head and arms against it, elbows bent at 90 degrees like a goal post. Slide your arms up the wall as far as you can while keeping your wrists and elbows touching it, then slide back down.', ['push'], ['shoulders', 'back'], 'mobility', 3],
  ['Doorway chest stretch', 'A door frame. Place your forearm on the frame with your elbow at shoulder height, then step forward gently through the doorway until you feel the stretch across your chest. Hold, then switch sides.', ['push'], ['chest', 'shoulders'], 'mobility', 3],
];

// Turn a row into a full exercise record with stable ids.
function seedExercises() {
  return SEED_ROWS.map(([name, description, movement, muscles, method, priority]) => ({
    id: 'seed:' + slug(name),
    name,
    description,
    notes: '',
    movementTypes: movement.map(m => 'movement:' + m),
    muscleGroups: muscles.map(m => 'muscle:' + m),
    methods: ['method:' + method],
    priority,
    builtIn: true,
    createdAt: 0,
    updatedAt: 0,
  }));
}
